    /// Append flat block ids requested by ctx_reduce to the durable per-session queue.
    /// Duplicate pending ids are ignored so repeated command delivery is harmless.
    pub fn append_pending_agent_drops(
        &self,
        session_id: &str,
        target_ids: &[String],
        queued_at_ms: i64,
    ) -> Result<usize, MemoryStoreError> {
        let outcome = self.append_pending_agent_drops_with_command(
            session_id,
            None,
            target_ids,
            queued_at_ms,
            false,
        )?;
        Ok(outcome.queued as usize)
    }

    /// Append ctx_reduce drops and, when supplied, durably record the command that requested
    /// them. A repeated command is acknowledged without touching pending queue rows.
    ///
    /// When `zero_targets` is true the ledger row is still recorded (idempotency correctness
    /// requires it — a retry of the same command_id must still dedupe), but the disposition
    /// is set to "no_targets" so the row is not counted as pending.
    pub fn append_pending_agent_drops_with_command(
        &self,
        session_id: &str,
        command_id: Option<&str>,
        target_ids: &[String],
        queued_at_ms: i64,
        zero_targets: bool,
    ) -> Result<AppendOutcome, MemoryStoreError> {
        let mut write = PreparedWrite::new(DurableWriteFamily::CommandLedgers);
        write.domain_owner(
            "session",
            session_id,
            active_scan_owner_key(&["reduce", command_id.unwrap_or("pending_drops")]),
        );
        write.existing_identity("session_id", session_id)?;
        if let Some(command_id) = command_id {
            let duplicate = self.inner.with_conn(|conn| {
                conn.query_row(
                    "SELECT EXISTS(SELECT 1 FROM reduce_command_ledger WHERE session_id = ?1 AND command_id = ?2)",
                    params![session_id, command_id],
                    |row| row.get::<_, bool>(0),
                )
            })?;
            if duplicate {
                return Ok(AppendOutcome {
                    queued: 0,
                    duplicate: true,
                    disposition: None,
                    inserted_target_ids: Vec::new(),
                });
            }
            write.identity("command_id", command_id)?;
        }
        for target_id in target_ids {
            write.identity("target_id", target_id.trim())?;
        }
        let outcome = write.execute(&self.inner, |coordinated| {
            let tx = coordinated.tx();
            let mut recorded_command = false;
            if let Some(command_id) = command_id {
                let recorded = tx.execute(
                    "INSERT OR IGNORE INTO reduce_command_ledger
                         (session_id, command_id, queued_at_ms)
                     VALUES (?1, ?2, ?3)",
                    params![session_id, command_id, queued_at_ms],
                )?;
                if recorded == 0 {
                    return Ok(WriteDisposition::Replay(AppendOutcome {
                        queued: 0,
                        duplicate: true,
                        disposition: None,
                        inserted_target_ids: Vec::new(),
                    }));
                }
                recorded_command = true;
            }

            let mut queued = 0u64;
            let mut inserted_target_ids = Vec::new();
            for target_id in target_ids {
                let target_id = target_id.trim();
                if target_id.is_empty() {
                    continue;
                }
                let inserted = tx.execute(
                    "INSERT OR IGNORE INTO pending_agent_drops
                         (session_id, target_id, queued_at, command_id)
                     VALUES (?1, ?2, ?3, ?4)",
                    params![session_id, target_id, queued_at_ms, command_id],
                )?;
                if inserted > 0 {
                    inserted_target_ids.push(target_id.to_string());
                }
                queued += inserted as u64;
            }

            // Command ids are lineage-durable. Pruning would make an old outcome-unknown
            // retry destructive again, so rows leave only with real lineage teardown.

            // When the caller resolved zero targets, mark the ledger row as terminal so it
            // is not counted among pending commands. The row still exists for idempotency.
            if zero_targets && let Some(command_id) = command_id {
                tx.execute(
                    "UPDATE reduce_command_ledger
                         SET disposition = 'no_targets'
                         WHERE session_id = ?1
                           AND command_id = ?2
                           AND disposition IS NULL",
                    params![session_id, command_id],
                )?;
            }

            let outcome = AppendOutcome {
                queued,
                duplicate: false,
                disposition: if zero_targets {
                    Some("no_targets".to_string())
                } else {
                    None
                },
                inserted_target_ids,
            };
            Ok(if recorded_command || queued != 0 {
                WriteDisposition::Applied(outcome)
            } else {
                WriteDisposition::Replay(outcome)
            })
        })?;
        Ok(outcome)
    }

    /// Load queued ctx_reduce drops in the deterministic drain order.
    pub fn load_pending_agent_drops(
        &self,
        session_id: &str,
    ) -> Result<Vec<PendingAgentDrop>, MemoryStoreError> {
        Ok(self.inner.with_conn(|conn| {
            let mut stmt = conn.prepare_cached(
                "SELECT p.id, p.target_id, p.queued_at, p.command_id,
                        l.first_applied_at_ms
                 FROM pending_agent_drops p
                 LEFT JOIN reduce_command_ledger l
                   ON l.session_id = p.session_id AND l.command_id = p.command_id
                 WHERE p.session_id = ?1
                 ORDER BY p.queued_at ASC, p.id ASC",
            )?;
            let rows = stmt.query_map(params![session_id], |r| {
                Ok(PendingAgentDrop {
                    id: r.get(0)?,
                    target_id: r.get(1)?,
                    queued_at_ms: r.get(2)?,
                    command_id: r.get(3)?,
                    command_first_applied_at_ms: r.get(4)?,
                })
            })?;
            let mut out = Vec::new();
            for row in rows {
                out.push(row?);
            }
            Ok(out)
        })?)
    }

    /// Mint tag rows for newly-observed block ids and return every requested row.
    /// Existing rows keep their original numbers; fresh rows consume the next numbers
    /// in the caller's order inside one transaction.
    // Production callers live module-side behind the test-support seeds; without that
    // feature only in-crate tests reach these write paths, so silence the lint there.
    #[cfg_attr(not(any(test, feature = "test-support")), allow(dead_code))]
    pub(crate) fn mint_or_get_tags(
        &self,
        session_id: &str,
        inputs: &[TagMintInput],
        created_at_ms: i64,
    ) -> Result<Vec<TagRow>, MemoryStoreError> {
        let mut write = PreparedWrite::new(DurableWriteFamily::Tags);
        write.domain_owner("session", session_id, "tags");
        write.existing_identity("session_id", session_id)?;
        let existing_ids = self.inner.with_conn(|conn| {
            let mut ids = HashSet::new();
            for input in inputs {
                let block_id = input.block_id.trim();
                if conn
                    .query_row(
                        "SELECT 1 FROM tags WHERE session_id = ?1 AND block_id = ?2",
                        params![session_id, block_id],
                        |_| Ok(()),
                    )
                    .optional()?
                    .is_some()
                {
                    ids.insert(block_id.to_string());
                }
            }
            Ok(ids)
        })?;
        let mut prepared_inputs = Vec::with_capacity(inputs.len());
        for input in inputs {
            let block_id = input.block_id.trim();
            if block_id.is_empty() {
                prepared_inputs.push(PreparedTagMint {
                    input: input.clone(),
                    insert_refusal: None,
                });
                continue;
            }
            let existed = existing_ids.contains(block_id);
            let first_scan = write.scans.len();
            if existed {
                // Existing block ids are valid during replay.
                write.existing_identity("block_id", block_id)?;
                write.existing_identity("kind", &input.kind)?;
            } else {
                write.identity("block_id", block_id)?;
                write.identity("kind", &input.kind)?;
            }
            let mut insert_refusal = write.scans[first_scan..]
                .iter()
                .any(|scan| !scan.redaction.detections.is_empty())
                .then_some(MemoryStoreError::Redaction(
                    RedactionErrorKind::SecretDetected,
                ));
            let source_bytes = match write.bytes("source_bytes", &input.source_bytes) {
                Ok(prepared) => prepared,
                Err(error) if existed => {
                    // Bytes the transaction never stores must not fail the call.
                    insert_refusal = insert_refusal.or(Some(error));
                    input.source_bytes.clone()
                }
                Err(error) => return Err(error),
            };
            prepared_inputs.push(PreparedTagMint {
                input: TagMintInput {
                    block_id: input.block_id.clone(),
                    kind: input.kind.clone(),
                    token_count: input.token_count,
                    source_bytes,
                },
                insert_refusal,
            });
        }
        write.execute(&self.inner, |coordinated| {
            let tx = coordinated.tx();
            let mut out = Vec::with_capacity(inputs.len());
            let mut inserted = false;
            for prepared in prepared_inputs {
                let PreparedTagMint {
                    input,
                    insert_refusal,
                } = prepared;
                let block_id = input.block_id.trim();
                if block_id.is_empty() {
                    continue;
                }
                if let Some(row) = tx
                    .prepare_cached(
                        "SELECT tag_number, block_id, kind, token_count, created_at_ms, source_bytes
                         FROM tags
                         WHERE session_id = ?1 AND block_id = ?2",
                    )?
                    .query_row(params![session_id, block_id], tag_row_from_sql)
                    .optional()?
                {
                    out.push(row);
                    continue;
                }
                if let Some(error) = insert_refusal {
                    // The unfenced read saw a row with this identity, but no row survives in
                    // this transaction.
                    return Err(rusqlite::Error::ToSqlConversionFailure(Box::new(error)));
                }
                let next = tx
                    .prepare_cached(
                        "SELECT COALESCE(MAX(tag_number), 0) + 1 FROM tags WHERE session_id = ?1",
                    )?
                    .query_row(params![session_id], |r| r.get::<_, i64>(0))?;
                tx.prepare_cached(
                    "INSERT INTO tags
                         (session_id, tag_number, block_id, kind, token_count, created_at_ms, source_bytes)
                     VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)",
                )?
                .execute(
                    params![
                        session_id,
                        next,
                        block_id,
                        input.kind.as_str(),
                        input.token_count.max(0),
                        created_at_ms,
                        input.source_bytes,
                    ],
                )?;
                out.push(TagRow {
                    tag_number: next,
                    block_id: block_id.to_string(),
                    kind: input.kind.clone(),
                    token_count: input.token_count.max(0),
                    created_at_ms,
                    source_bytes: input.source_bytes.clone(),
                });
                inserted = true;
            }
            Ok(if inserted {
                WriteDisposition::Applied(out)
            } else {
                WriteDisposition::Replay(out)
            })
        })
    }

    /// Load all minted tags for a session in tag-number order. This is the cold baseline fill.
    pub fn load_tags_for_session(&self, session_id: &str) -> Result<Vec<TagRow>, MemoryStoreError> {
        Ok(self.inner.with_conn(|conn| {
            let mut stmt = conn.prepare_cached(
                "SELECT tag_number, block_id, kind, token_count, created_at_ms, source_bytes
                 FROM tags
                 WHERE session_id = ?1
                 ORDER BY tag_number ASC",
            )?;
            let rows = stmt.query_map(params![session_id], tag_row_from_sql)?;
            let mut out = Vec::new();
            for row in rows {
                out.push(row?);
            }
            Ok(out)
        })?)
    }

    /// Load only rows minted after `after_tag_number`, in primary-key order.
    pub fn load_tags_after(
        &self,
        session_id: &str,
        after_tag_number: i64,
    ) -> Result<Vec<TagRow>, MemoryStoreError> {
        Ok(self.inner.with_conn(|conn| {
            let mut stmt = conn.prepare_cached(
                "SELECT tag_number, block_id, kind, token_count, created_at_ms, source_bytes
                 FROM tags
                 WHERE session_id = ?1 AND tag_number > ?2
                 ORDER BY tag_number ASC",
            )?;
            let rows = stmt.query_map(params![session_id, after_tag_number], tag_row_from_sql)?;
            rows.collect::<Result<Vec<_>, _>>()
        })?)
    }

    /// Return the trigger-maintained tag identity for cache validation without reading blobs.
    ///
    /// Triggers maintain count and max during rare writes; replacements and deletions derive a
    /// fresh max from the primary-key prefix. Steady transforms read this one small row instead of
    /// scanning immutable tag payloads.
    pub fn tag_cache_summary(&self, session_id: &str) -> Result<TagCacheSummary, MemoryStoreError> {
        Ok(self.inner.with_conn(|conn| {
            conn.prepare_cached(
                "SELECT generation, tag_count, max_tag_number
                   FROM tag_cache_generations
                  WHERE session_id = ?1",
            )?
            .query_row(params![session_id], |row| {
                Ok(TagCacheSummary {
                    generation: row.get::<_, i64>(0)?.max(0) as u64,
                    count: row.get::<_, i64>(1)?.max(0) as usize,
                    max_tag_number: row.get(2)?,
                })
            })
            .optional()
            .map(|summary| summary.unwrap_or_default())
        })?)
    }

    /// Load only the fields used to decide whether native reasoning is old enough to clear.
    pub fn load_tag_numbers_for_session(
        &self,
        session_id: &str,
    ) -> Result<Vec<TagNumberRow>, MemoryStoreError> {
        #[cfg(any(test, feature = "test-support"))]
        self.tag_number_query_count
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        Ok(self.inner.with_conn(|conn| {
            let mut stmt = conn.prepare_cached(
                "SELECT block_id, tag_number FROM tags
                 WHERE session_id = ?1 ORDER BY tag_number ASC",
            )?;
            let rows = stmt.query_map(params![session_id], |row| {
                Ok(TagNumberRow {
                    block_id: row.get(0)?,
                    tag_number: row.get(1)?,
                })
            })?;
            rows.collect::<Result<Vec<_>, _>>()
        })?)
    }

    /// Load only tag-number rows minted after `after_tag_number`, in primary-key order.
    pub fn load_tag_numbers_after(
        &self,
        session_id: &str,
        after_tag_number: i64,
    ) -> Result<Vec<TagNumberRow>, MemoryStoreError> {
        #[cfg(any(test, feature = "test-support"))]
        self.tag_number_query_count
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        Ok(self.inner.with_conn(|conn| {
            let mut stmt = conn.prepare_cached(
                "SELECT block_id, tag_number FROM tags
                 WHERE session_id = ?1 AND tag_number > ?2
                 ORDER BY tag_number ASC",
            )?;
            let rows = stmt.query_map(params![session_id, after_tag_number], |row| {
                Ok(TagNumberRow {
                    block_id: row.get(0)?,
                    tag_number: row.get(1)?,
                })
            })?;
            rows.collect::<Result<Vec<_>, _>>()
        })?)
    }

    #[cfg(any(test, feature = "test-support"))]
    pub fn tag_number_query_count_for_test(&self) -> usize {
        self.tag_number_query_count
            .load(std::sync::atomic::Ordering::Relaxed)
    }

    /// Test-only raw SQL seam for proving trigger-backed cache invalidation against out-of-band
    /// writes. Production tag changes use the fenced transform transaction instead.
    #[cfg(any(test, feature = "test-support"))]
    pub fn execute_tag_sql_for_test(&self, sql: &str) -> Result<(), MemoryStoreError> {
        self.inner.with_conn_unfenced(|conn| {
            conn.execute_batch(sql)?;
            Ok(())
        })?;
        Ok(())
    }

    /// Sum stored token counts for a caller-selected block-id set.
    pub fn sum_tag_token_counts_for_blocks(
        &self,
        session_id: &str,
        block_ids: &HashSet<String>,
    ) -> Result<i64, MemoryStoreError> {
        if block_ids.is_empty() {
            return Ok(0);
        }
        let rows = self.load_tags_for_session(session_id)?;
        Ok(rows
            .into_iter()
            .filter(|row| block_ids.contains(&row.block_id))
            .map(|row| row.token_count.max(0))
            .sum())
    }

    /// Insert one Channel-1 append row if this block has not already received one.
    #[cfg_attr(not(any(test, feature = "test-support")), allow(dead_code))]
    pub(crate) fn append_channel1_nudge(
        &self,
        session_id: &str,
        block_id: &str,
        reminder_text: &str,
        fired_at_ms: i64,
    ) -> Result<bool, MemoryStoreError> {
        let mut write = PreparedWrite::new(DurableWriteFamily::TransformOverlays);
        write.domain_owner("session", session_id, "channel1_appends");
        write.existing_identity("session_id", session_id)?;
        write.existing_identity("channel1_block_id", block_id)?;
        let reminder_text = write.content("reminder_text", reminder_text)?;
        write.execute(&self.inner, |coordinated| {
            let tx = coordinated.tx();
            let exists = tx.query_row(
                "SELECT EXISTS(SELECT 1 FROM channel1_appends
                  WHERE session_id = ?1 AND block_id = ?2)",
                params![session_id, block_id],
                |row| row.get::<_, bool>(0),
            )?;
            if exists {
                return Ok(WriteDisposition::Replay(false));
            }
            coordinated
                .prepared
                .borrow()
                .reject_recorded_identities(&["channel1_block_id"])
                .map_err(|error| rusqlite::Error::ToSqlConversionFailure(Box::new(error)))?;
            let inserted = tx.execute(
                "INSERT OR IGNORE INTO channel1_appends
                     (session_id, block_id, reminder_text, fired_at_ms)
                 VALUES (?1, ?2, ?3, ?4)",
                params![session_id, block_id, reminder_text, fired_at_ms],
            )?;
            Ok(WriteDisposition::Applied(inserted > 0))
        })
    }

    /// Load stored Channel-1 append bytes in deterministic order.
    pub fn load_channel1_appends(
        &self,
        session_id: &str,
    ) -> Result<Vec<Channel1AppendRow>, MemoryStoreError> {
        Ok(self.inner.with_conn(|conn| {
            let mut stmt = conn.prepare_cached(
                "SELECT block_id, reminder_text, fired_at_ms
                 FROM channel1_appends
                 WHERE session_id = ?1
                 ORDER BY fired_at_ms ASC, block_id ASC",
            )?;
            let rows = stmt.query_map(params![session_id], |r| {
                Ok(Channel1AppendRow {
                    block_id: r.get(0)?,
                    reminder_text: r.get(1)?,
                    fired_at_ms: r.get(2)?,
                })
            })?;
            let mut out = Vec::new();
            for row in rows {
                out.push(row?);
            }
            Ok(out)
        })?)
    }

    /// Read the ordinal frontier used to avoid first-applying overlays to closed turns.
    /// A missing row is distinct from ordinal zero, which is a valid first message.
    pub fn overlay_watermark(&self, session_id: &str) -> Result<Option<u64>, MemoryStoreError> {
        let value = self.inner.with_conn(|conn| {
            conn.query_row(
                "SELECT max_seen_ordinal FROM overlay_frontiers WHERE session_id = ?1",
                params![session_id],
                |row| row.get::<_, i64>(0),
            )
            .optional()
        })?;
        Ok(value.map(|ordinal| ordinal.max(0) as u64))
    }

    /// Freeze first-sight overlay decisions and advance the pass watermark atomically.
    /// Every candidate is compared with the watermark from before this transaction. A
    /// racing hint writer returns the already-stored bytes so both callers render the
    /// same canonical decision.
    #[cfg(test)]
    pub(crate) fn apply_active_overlay_decisions(
        &self,
        session_id: &str,
        max_seen_ordinal: u64,
        temporal_marks: &[TemporalMarkInput],
        user_hint: Option<&UserHintDecisionInput>,
        created_at: i64,
    ) -> Result<Option<UserHintRow>, MemoryStoreError> {
        let max_seen_ordinal = i64::try_from(max_seen_ordinal).map_err(|_| {
            MemoryStoreError::Serde("message ordinal exceeds SQLite range".to_string())
        })?;
        let temporal_marks = temporal_marks
            .iter()
            .map(|mark| {
                i64::try_from(mark.ordinal)
                    .map(|ordinal| (ordinal, mark))
                    .map_err(|_| {
                        MemoryStoreError::Serde("message ordinal exceeds SQLite range".to_string())
                    })
            })
            .collect::<Result<Vec<_>, _>>()?;
        let hint_ordinal = user_hint
            .map(|hint| -> Result<_, MemoryStoreError> {
                i64::try_from(hint.ordinal).map_err(|_| {
                    MemoryStoreError::Serde("message ordinal exceeds SQLite range".to_string())
                })
            })
            .transpose()?;

        Ok(self.inner.with_conn_fenced(|tx| {
            let previous = tx
                .query_row(
                    "SELECT max_seen_ordinal
                     FROM overlay_frontiers
                     WHERE session_id = ?1",
                    params![session_id],
                    |row| row.get::<_, i64>(0),
                )
                .optional()?;

            for (ordinal, mark) in &temporal_marks {
                if previous.is_none_or(|frontier| *ordinal > frontier) {
                    tx.execute(
                        "INSERT OR IGNORE INTO temporal_marks
                             (session_id, block_id, marker_text, created_at)
                         VALUES (?1, ?2, ?3, ?4)",
                        params![session_id, mark.block_id, mark.marker_text, created_at],
                    )?;
                }
            }

            let canonical_hint = if let Some(hint) = user_hint {
                let existing = tx
                    .query_row(
                        "SELECT block_id, hint_text, created_at
                         FROM user_hints
                         WHERE session_id = ?1 AND block_id = ?2",
                        params![session_id, hint.block_id],
                        |row| {
                            Ok(UserHintRow {
                                block_id: row.get(0)?,
                                hint_text: row.get(1)?,
                                created_at: row.get(2)?,
                            })
                        },
                    )
                    .optional()?;
                if existing.is_some()
                    || hint_ordinal
                        .is_some_and(|ordinal| previous.is_some_and(|frontier| ordinal <= frontier))
                {
                    existing
                } else {
                    tx.execute(
                        "INSERT OR IGNORE INTO user_hints
                             (session_id, block_id, hint_text, created_at)
                         VALUES (?1, ?2, ?3, ?4)",
                        params![session_id, hint.block_id, hint.hint_text, created_at],
                    )?;
                    tx.query_row(
                        "SELECT block_id, hint_text, created_at
                         FROM user_hints
                         WHERE session_id = ?1 AND block_id = ?2",
                        params![session_id, hint.block_id],
                        |row| {
                            Ok(UserHintRow {
                                block_id: row.get(0)?,
                                hint_text: row.get(1)?,
                                created_at: row.get(2)?,
                            })
                        },
                    )
                    .optional()?
                }
            } else {
                None
            };

            tx.execute(
                "INSERT INTO overlay_frontiers (session_id, max_seen_ordinal)
                 VALUES (?1, ?2)
                 ON CONFLICT(session_id) DO UPDATE SET
                     max_seen_ordinal = MAX(max_seen_ordinal, excluded.max_seen_ordinal)",
                params![session_id, max_seen_ordinal],
            )?;
            Ok(canonical_hint)
        })?)
    }

    /// Persist one auto-search decision, including an empty no-result decision.
    #[cfg(test)]
    pub(crate) fn append_user_hint(
        &self,
        session_id: &str,
        block_id: &str,
        hint_text: &str,
        created_at: i64,
    ) -> Result<bool, MemoryStoreError> {
        let mut write = PreparedWrite::new(DurableWriteFamily::TransformOverlays);
        write.domain_owner("session", session_id, "user_hints");
        write.existing_identity("session_id", session_id)?;
        write.existing_identity("user_hint_block_id", block_id)?;
        let hint_text = write.content("user_hint_text", hint_text)?;
        write.execute(&self.inner, |coordinated| {
            let tx = coordinated.tx();
            let exists = tx.query_row(
                "SELECT EXISTS(SELECT 1 FROM user_hints
                  WHERE session_id = ?1 AND block_id = ?2)",
                params![session_id, block_id],
                |row| row.get::<_, bool>(0),
            )?;
            if exists {
                return Ok(WriteDisposition::Replay(false));
            }
            coordinated
                .prepared
                .borrow()
                .reject_recorded_identities(&["user_hint_block_id"])
                .map_err(|error| rusqlite::Error::ToSqlConversionFailure(Box::new(error)))?;
            let inserted = tx.execute(
                "INSERT OR IGNORE INTO user_hints
                     (session_id, block_id, hint_text, created_at)
                 VALUES (?1, ?2, ?3, ?4)",
                params![session_id, block_id, hint_text, created_at],
            )?;
            Ok(WriteDisposition::Applied(inserted > 0))
        })
    }

    /// Canonical test descriptor: a `memory`-namespace module store on
    /// `<dir>/memory.sqlite`. Unit tests reach it through `cfg(test)`; this
    /// crate's integration tests and sibling crates through the
    /// `test-support` feature.
    #[cfg(any(test, feature = "test-support"))]
    pub fn test_descriptor(dir: &std::path::Path, module_id: &str) -> StorageDescriptor {
        use storage::{Isolation, StorageBackend};
        StorageDescriptor {
            module_id: module_id.to_string(),
            storage_namespace: "memory".to_string(),
            isolation: Isolation::Module,
            backend: StorageBackend::Sqlite {
                path: dir.join("memory.sqlite").to_string_lossy().into_owned(),
            },
        }
    }

    /// Opens the [`MemoryStore::test_descriptor`] fixture.
    #[cfg(any(test, feature = "test-support"))]
    pub fn open_for_test(dir: &std::path::Path, module_id: &str) -> MemoryStore {
        MemoryStore::open(&Self::test_descriptor(dir, module_id)).expect("open test store")
    }

