    #[test]
    fn project_mural_artifact_upsert_is_hash_gated() {
        let dir = tempfile::tempdir().unwrap();
        let store = MemoryStore::open(&descriptor(dir.path())).unwrap();

        assert!(
            store
                .upsert_project_mural_artifact(
                    "git:project",
                    b"data:image/png;base64,YQ==",
                    "mural-a",
                    100,
                )
                .unwrap()
        );
        let first = store
            .load_project_mural_artifact("git:project")
            .unwrap()
            .unwrap();
        assert_eq!(first.data_url, b"data:image/png;base64,YQ==");
        assert_eq!(first.content_hash, "mural-a");
        assert_eq!(first.updated_at, 100);

        assert!(
            !store
                .upsert_project_mural_artifact(
                    "git:project",
                    b"data:image/png;base64,unexpected-but-same-hash",
                    "mural-a",
                    200,
                )
                .unwrap()
        );
        let unchanged = store
            .load_project_mural_artifact("git:project")
            .unwrap()
            .unwrap();
        assert_eq!(
            unchanged, first,
            "same hash must not bump artifact identity"
        );

        assert!(
            store
                .upsert_project_mural_artifact(
                    "git:project",
                    b"data:image/png;base64,Yg==",
                    "mural-b",
                    300,
                )
                .unwrap()
        );
        assert_eq!(
            store
                .load_project_mural_artifact("git:project")
                .unwrap()
                .unwrap(),
            ProjectMuralArtifact {
                project_path: "git:project".to_string(),
                data_url: b"data:image/png;base64,Yg==".to_vec(),
                content_hash: "mural-b".to_string(),
                updated_at: 300,
            }
        );
    }

    #[test]
    fn every_durable_write_family_is_declared_once_with_a_distinct_owner_kind() {
        let mut seen_families = BTreeSet::new();
        let mut seen_owner_kinds = BTreeSet::new();
        for entry in DURABLE_WRITE_REGISTRY {
            assert!(
                seen_families.insert(entry.family),
                "{:?} is declared more than once",
                entry.family
            );
            let owner_kind = entry.family.owner_kind();
            assert!(
                !owner_kind.is_empty(),
                "{:?} has an empty owner kind",
                entry.family
            );
            assert!(
                seen_owner_kinds.insert(owner_kind),
                "owner kind {owner_kind} is claimed by more than one family"
            );
            assert!(
                !entry.preparation.is_empty(),
                "{:?} does not name its preparation path",
                entry.family
            );
            assert!(
                !entry.test.is_empty(),
                "{:?} does not name a proving test",
                entry.family
            );
        }
        // `PreparedWrite::new` resolves the registration, so an undeclared family panics on
        // first use rather than writing without a declared policy.
        for family in DurableWriteFamily::ALL {
            assert!(
                seen_families.contains(family),
                "{family:?} is missing from DURABLE_WRITE_REGISTRY"
            );
        }
        assert_eq!(seen_families.len(), DurableWriteFamily::ALL.len());
    }

