    /// A preserved existing identity stores its value verbatim and records a
    /// `preserve` audit action, never a `substitute` one.
    #[test]
    fn detection_receipts_record_preserve_for_existing_identities() {
        let dir = tempfile::tempdir().unwrap();
        let store = MemoryStore::open(&descriptor(dir.path())).unwrap();
        let secret = "x_auth_token=hunter-two";

        let mut write = PreparedWrite::new(DurableWriteFamily::Compartments);
        write.domain_owner("session", "ses_actions", "receipt_probe");
        let kept = write.existing_identity("unit_key", secret).unwrap();
        assert_eq!(kept, secret, "an existing identity is stored verbatim");
        let substituted = write.content("content", secret).unwrap();
        assert_ne!(
            substituted, secret,
            "content preparation substitutes the detected span"
        );
        write
            .execute(&store.inner, |_| Ok(WriteDisposition::Applied(())))
            .unwrap();

        let actions: Vec<(String, String)> = store
            .inner
            .with_conn(|conn| {
                let mut statement = conn.prepare(
                    "SELECT DISTINCT copies.field_id, det.action
                       FROM scan_detections det
                       JOIN scan_owner_copies copies USING(scan_id)
                      ORDER BY copies.field_id",
                )?;
                let rows = statement
                    .query_map([], |row| Ok((row.get(0)?, row.get(1)?)))?
                    .collect::<rusqlite::Result<Vec<_>>>()?;
                Ok(rows)
            })
            .unwrap();
        assert_eq!(
            actions,
            vec![
                ("content".to_string(), "substitute".to_string()),
                ("unit_key".to_string(), "preserve".to_string()),
            ],
            "each detection receipt must carry the disposition its field actually took"
        );
    }

    #[test]
    fn compartments_roundtrip_chronological_with_tiers_and_legacy() {
        let dir = tempfile::tempdir().unwrap();
        let store = MemoryStore::open(&descriptor(dir.path())).unwrap();
        assert!(store.load_compartments("ses_a").unwrap().is_empty());

        let comps = vec![
            StoredCompartment {
                sequence: 1,
                start_message: 1,
                end_message: 9,
                title: "oldest legacy".into(),
                content: "U: flat body".into(),
                legacy: 1,
                importance: 50,
                created_at: 100,
                ..Default::default()
            },
            StoredCompartment {
                sequence: 2,
                start_message: 10,
                end_message: 19,
                start_date: Some("2026-01-02".into()),
                end_date: Some("2026-01-03".into()),
                title: "v2 row".into(),
                content: "P1 full".into(),
                p1: Some("P1 full".into()),
                p2: Some("P2 dense".into()),
                p3: Some("P3".into()),
                p4: None,
                importance: 80,
                episode_type: Some("design,feature".into()),
                legacy: 0,
                created_at: 200,
                ..Default::default()
            },
        ];
        store.replace_compartments("ses_a", &comps).unwrap();

        let read = store.load_compartments("ses_a").unwrap();
        assert_eq!(
            read, comps,
            "chronological round-trip incl NULL p4 + tiers + legacy"
        );
        assert_eq!(read[0].sequence, 1, "oldest first");

        // a wholesale replace fully supplants the prior set
        let replacement = vec![StoredCompartment {
            sequence: 1,
            title: "only".into(),
            content: "x".into(),
            importance: 50,
            ..Default::default()
        }];
        store.replace_compartments("ses_a", &replacement).unwrap();
        let read2 = store.load_compartments("ses_a").unwrap();
        assert_eq!(read2.len(), 1);
        assert_eq!(read2[0].title, "only");

        // distinct sessions are isolated
        assert!(store.load_compartments("ses_b").unwrap().is_empty());
    }

    #[test]
    fn max_compartment_end_ordinal_matches_full_compartment_load() {
        let dir = tempfile::tempdir().unwrap();
        let store = MemoryStore::open(&descriptor(dir.path())).unwrap();
        let compartments = vec![
            StoredCompartment {
                sequence: 1,
                start_message: 1,
                end_message: 8,
                title: "first".into(),
                content: "one".into(),
                ..Default::default()
            },
            StoredCompartment {
                sequence: 2,
                start_message: 9,
                end_message: 23,
                title: "second".into(),
                content: "two".into(),
                ..Default::default()
            },
        ];
        store
            .replace_compartments("ordinal-session", &compartments)
            .unwrap();

        let full_max = store
            .load_compartments("ordinal-session")
            .unwrap()
            .iter()
            .map(|compartment| compartment.end_message)
            .max()
            .unwrap_or(0);
        assert_eq!(
            store
                .max_compartment_end_ordinal("ordinal-session")
                .unwrap(),
            full_max
        );
        assert_eq!(
            store.max_compartment_end_ordinal("empty-session").unwrap(),
            0
        );

        let details = store
            .inner
            .with_conn(|conn| {
                let mut statement = conn.prepare_cached(
                    "EXPLAIN QUERY PLAN
                     SELECT COALESCE(MAX(end_message), 0)
                       FROM compartments WHERE session_id = ?1",
                )?;
                let rows = statement
                    .query_map(params!["ordinal-session"], |row| row.get::<_, String>(3))?
                    .collect::<Result<Vec<_>, _>>()?;
                Ok(rows)
            })
            .unwrap();
        assert!(
            details.iter().any(|detail| {
                detail.contains("USING COVERING INDEX idx_compartments_session_end_message")
            }),
            "compartment max must use the covering end-ordinal index: {details:?}"
        );
    }

    #[test]
    fn active_user_memories_ordered_promoted_then_id() {
        let dir = tempfile::tempdir().unwrap();
        let store = MemoryStore::open(&descriptor(dir.path())).unwrap();
        let insert = |id: i64, content: &str, status: &str, promoted: i64| {
            store
                .inner
                .with_conn_fenced(|tx| {
                    tx.execute(
                        "INSERT INTO user_memories (id, content, status, promoted_at)
                         VALUES (?1, ?2, ?3, ?4)",
                        params![id, content, status, promoted],
                    )?;
                    Ok(())
                })
                .unwrap();
        };
        // two share promoted_at=100 → id breaks the tie deterministically (3 before 4).
        insert(1, "first", "active", 50);
        insert(4, "tie-later-id", "active", 100);
        insert(3, "tie-earlier-id", "active", 100);
        insert(2, "archived", "archived", 10); // status != active → excluded from the result

        let got = store.load_active_user_memories().unwrap();
        assert_eq!(got, vec!["first", "tie-earlier-id", "tie-later-id"]);
    }

    #[test]
    fn append_compartments_rejects_overlapping_ranges_without_partial_rows() {
        let dir = tempfile::tempdir().unwrap();
        let store = MemoryStore::open(&descriptor(dir.path())).unwrap();
        let compartment = |sequence: i64,
                           start_message: i64,
                           end_message: i64,
                           end_message_id: &str| StoredCompartment {
            sequence,
            start_message,
            end_message,
            end_message_id: end_message_id.to_string(),
            title: "summary".to_string(),
            content: "summary".to_string(),
            ..Default::default()
        };
        store
            .replace_compartments("ses", &[compartment(1, 1, 5, "m5")])
            .unwrap();

        let error = store
            .append_compartments("ses", &[compartment(99, 5, 8, "m8")])
            .unwrap_err();
        assert!(matches!(
            error,
            MemoryStoreError::CompartmentRangeOverlap {
                existing_sequence: 1,
                incoming_start_message: 5,
                incoming_end_message: 8,
            }
        ));
        let rows = store.load_compartments("ses").unwrap();
        assert_eq!(rows.len(), 1, "a rejected append must stay atomic");
        assert_eq!(rows[0].sequence, 1);

        store
            .append_compartments("ses", &[compartment(99, 6, 8, "m8")])
            .unwrap();
        let rows = store.load_compartments("ses").unwrap();
        assert_eq!(rows.len(), 2, "a disjoint append must remain legal");
        assert_eq!(rows[1].sequence, 2, "append still owns durable numbering");
    }

