    type SectionSnapshot = (Vec<(i64, String)>, Vec<(i64, String, String)>);

    fn section_snapshot(store: &MemoryStore) -> SectionSnapshot {
        store
            .inner
            .with_conn(|conn| {
                let profiles = conn
                    .prepare("SELECT id, content FROM user_memories ORDER BY id")?
                    .query_map([], |row| Ok((row.get(0)?, row.get(1)?)))?
                    .collect::<Result<Vec<(i64, String)>, _>>()?;
                let workspaces = conn
                    .prepare(
                        "SELECT workspace.id, member.project_path, member.display_name
                           FROM workspaces workspace
                           JOIN workspace_members member ON member.workspace_id = workspace.id
                          ORDER BY workspace.id, member.project_path",
                    )?
                    .query_map([], |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)))?
                    .collect::<Result<Vec<(i64, String, String)>, _>>()?;
                Ok((profiles, workspaces))
            })
            .unwrap()
    }

    #[test]
    fn state_sync_sections_distinguish_absent_empty_and_legacy_always_present() {
        let workspace_a = ModuleWorkspaceRow {
            name: "workspace-a".to_string(),
            share_categories: vec!["CONSTRAINTS".to_string()],
            members: vec![ModuleWorkspaceMemberRow {
                project_path: "project".to_string(),
                display_name: "project".to_string(),
                display_path: "project".to_string(),
            }],
        };
        let workspace_b = ModuleWorkspaceRow {
            name: "workspace-b".to_string(),
            ..workspace_a.clone()
        };
        let profile_a = vec!["profile-a".to_string()];
        let profile_b = vec!["profile-b".to_string()];

        let mixed_dir = tempfile::tempdir().unwrap();
        let mixed = store(mixed_dir.path());
        apply_state_sync_sections(&mixed, 0, Some(&profile_a), true, Some(&workspace_a));
        let before_absent = section_snapshot(&mixed);
        apply_state_sync_sections(&mixed, 1, None, false, None);
        assert_eq!(
            section_snapshot(&mixed),
            before_absent,
            "absent sections must be untouched"
        );
        apply_state_sync_sections(&mixed, 2, Some(&profile_b), true, Some(&workspace_b));
        let mixed_final = section_snapshot(&mixed);

        let always_dir = tempfile::tempdir().unwrap();
        let always = store(always_dir.path());
        apply_state_sync_sections(&always, 0, Some(&profile_a), true, Some(&workspace_a));
        apply_state_sync_sections(&always, 1, Some(&profile_a), true, Some(&workspace_a));
        apply_state_sync_sections(&always, 2, Some(&profile_b), true, Some(&workspace_b));
        let always_final = section_snapshot(&always);
        assert_eq!(
            mixed_final.0.iter().map(|row| &row.1).collect::<Vec<_>>(),
            vec![&"profile-b".to_string()]
        );
        assert_eq!(
            mixed_final.1.iter().map(|row| &row.1).collect::<Vec<_>>(),
            vec![&"project".to_string()]
        );
        assert_eq!(
            mixed_final.0.iter().map(|row| &row.1).collect::<Vec<_>>(),
            always_final.0.iter().map(|row| &row.1).collect::<Vec<_>>(),
        );
        assert_eq!(
            mixed_final
                .1
                .iter()
                .map(|row| (&row.1, &row.2))
                .collect::<Vec<_>>(),
            always_final
                .1
                .iter()
                .map(|row| (&row.1, &row.2))
                .collect::<Vec<_>>(),
        );

        apply_state_sync_sections(&mixed, 3, Some(&[]), true, None);
        assert_eq!(section_snapshot(&mixed), (Vec::new(), Vec::new()));
    }

    #[test]
    fn authority_note_seed_frame_uses_one_fenced_transaction_and_is_idempotent() {
        let dir = tempfile::tempdir().unwrap();
        let store = store(dir.path());
        let rows = (1..=8)
            .map(|source_row_id| AuthoritySeedRow {
                source_row_id,
                snapshot: serde_json::json!({
                    "id": source_row_id,
                    "project_path": "project",
                    "session_id": format!("session-{source_row_id}"),
                    "content": format!("note {source_row_id} password=seed-secret"),
                    "status": "active"
                }),
            })
            .collect::<Vec<_>>();
        let before = store.authority_seed_transaction_count_for_test();
        let first = store
            .seed_authority_rows("store-uuid", "project", "notes", &rows)
            .unwrap();
        assert_eq!(
            store.authority_seed_transaction_count_for_test(),
            before + 1,
            "one wire frame must use one fenced transaction regardless of row count"
        );
        let state_before_retry = store
            .authority_seed_checksum("store-uuid", "project", "notes")
            .unwrap();
        let second = store
            .seed_authority_rows("store-uuid", "project", "notes", &rows)
            .unwrap();
        assert_eq!(
            first, second,
            "re-seeding a frame reuses source-key identities"
        );
        assert_eq!(
            store.authority_seed_transaction_count_for_test(),
            before + 2
        );
        assert_eq!(
            store
                .authority_seed_checksum("store-uuid", "project", "notes")
                .unwrap(),
            state_before_retry,
            "re-seeding the same frame must be a no-op"
        );
        assert!(
            store
                .read_project_notes("project", None, &["active"], 20, 0)
                .unwrap()
                .iter()
                .all(|note| note.content.contains("password=<REDACTED:password>")
                    && !note.content.contains("seed-secret"))
        );
    }

    #[test]
    fn authority_state_machine_persists_generations_and_drain_journal() {
        let dir = tempfile::tempdir().unwrap();
        let store = store(dir.path());
        store
            .bind_authority_route("store-uuid", "project", "/repo")
            .unwrap();
        let preparing = store
            .authority_begin_prepare("store-uuid", "project", "memories")
            .unwrap();
        assert_eq!(preparing.state, "PREPARING");
        assert_eq!(preparing.generation, 1);
        assert_eq!(
            store
                .authority_project_for_route("/repo", "memories")
                .unwrap(),
            None,
            "PREPARING must keep transforms on the complete TypeScript snapshot"
        );
        let module = store
            .authority_finish_prepare(
                "store-uuid",
                "project",
                "memories",
                preparing.generation,
                "hash",
                "hash",
                true,
            )
            .unwrap();
        assert_eq!(module.state, "MODULE");
        assert_eq!(module.generation, 2);
        assert_eq!(
            store
                .authority_project_for_route("/repo", "memories")
                .unwrap()
                .as_deref(),
            Some("project")
        );
        let draining = store
            .authority_begin_drain("store-uuid", "project", "memories", "lease", 100, 0)
            .unwrap();
        assert_eq!(draining.state, "DRAINING");
        assert_eq!(draining.captured_upper_bound, Some(0));
        assert_eq!(
            store
                .authority_project_for_route("/repo", "memories")
                .unwrap()
                .as_deref(),
            Some("project")
        );
        let token = draining.coordinator_token.clone().expect("token minted");
        let stepped = store
            .authority_drain_step(
                "store-uuid",
                "project",
                "memories",
                draining.generation,
                "seed",
                Some(0),
                &token,
                0,
            )
            .unwrap();
        assert!(stepped.step_seed);
    }

    #[test]
    fn authority_drain_begin_resumes_each_crash_journal_position() {
        for completed_steps in [0usize, 3, 6] {
            let dir = tempfile::tempdir().unwrap();
            let store = store(dir.path());
            let preparing = store
                .authority_begin_prepare("store-uuid", "project", "memories")
                .unwrap();
            store
                .authority_finish_prepare(
                    "store-uuid",
                    "project",
                    "memories",
                    preparing.generation,
                    "hash",
                    "hash",
                    true,
                )
                .unwrap();
            let draining = store
                .authority_begin_drain("store-uuid", "project", "memories", "coordinator", 100, 0)
                .unwrap();
            let token = draining.coordinator_token.clone().expect("token minted");
            let steps = [
                "seed",
                "memories",
                "notes",
                "compartments",
                "reconcile",
                "verify",
            ];
            for step in steps.iter().take(completed_steps) {
                store
                    .authority_drain_step(
                        "store-uuid",
                        "project",
                        "memories",
                        draining.generation,
                        step,
                        Some(0),
                        &token,
                        0,
                    )
                    .unwrap();
            }

            let resumed = store
                .authority_begin_drain("store-uuid", "project", "memories", "coordinator", 200, 101)
                .unwrap();
            assert_eq!(resumed.generation, draining.generation);
            assert_eq!(resumed.captured_upper_bound, draining.captured_upper_bound);
            let resume_token = resumed.coordinator_token.clone().expect("resume token");
            assert_ne!(
                resume_token, token,
                "resume mints a fresh coordinator token"
            );
            for step in steps.iter().skip(completed_steps) {
                store
                    .authority_drain_step(
                        "store-uuid",
                        "project",
                        "memories",
                        resumed.generation,
                        step,
                        Some(0),
                        &resume_token,
                        101,
                    )
                    .unwrap();
            }
            let finished = store
                .authority_finish_drain(
                    "store-uuid",
                    "project",
                    "memories",
                    resumed.generation,
                    "hash",
                    "hash",
                    true,
                    &resume_token,
                    101,
                )
                .unwrap();
            assert_eq!(finished.state, "TS");
        }
    }

    const DRAIN_STEPS: [&str; 6] = [
        "seed",
        "memories",
        "notes",
        "compartments",
        "reconcile",
        "verify",
    ];

    fn mark_every_drain_step(store: &MemoryStore, row: &AuthorityRow, now_ms: i64) {
        let token = row.coordinator_token.as_deref().expect("coordinator token");
        for step in DRAIN_STEPS {
            store
                .authority_drain_step(
                    &row.context_store_uuid,
                    &row.project,
                    &row.domain,
                    row.generation,
                    step,
                    Some(0),
                    token,
                    now_ms,
                )
                .unwrap();
        }
    }

    /// A late changefeed append widens `captured_upper_bound` on resume and clears
    /// the completed step flags; `authority_finish_drain` stays blocked until every
    /// step covers the new capture.
    #[test]
    fn authority_drain_resume_after_late_append_resets_completed_steps() {
        let dir = tempfile::tempdir().unwrap();
        let store = store(dir.path());
        let preparing = store
            .authority_begin_prepare("store-uuid", "project", "notes")
            .unwrap();
        store
            .authority_finish_prepare(
                "store-uuid",
                "project",
                "notes",
                preparing.generation,
                "hash",
                "hash",
                true,
            )
            .unwrap();
        let draining = store
            .authority_begin_drain("store-uuid", "project", "notes", "coordinator", 100, 0)
            .unwrap();
        let captured = draining.captured_upper_bound.expect("captured feed head");
        mark_every_drain_step(&store, &draining, 0);

        store
            .inner
            .with_conn_unfenced(|conn| {
                conn.execute(
                    "INSERT INTO changefeed(domain, op, module_row_id, full_row_snapshot, content_hash)
                     VALUES ('notes', 'insert', 1, '{}', 'late')",
                    [],
                )
                .map(drop)
            })
            .unwrap();

        let token = draining
            .coordinator_token
            .as_deref()
            .expect("coordinator token");
        assert!(matches!(
            store.authority_finish_drain(
                "store-uuid",
                "project",
                "notes",
                draining.generation,
                "hash",
                "hash",
                true,
                token,
                1,
            ),
            Err(MemoryStoreError::AuthorityFeedHeadAdvanced { .. })
        ));

        let resumed = store
            .authority_begin_drain("store-uuid", "project", "notes", "coordinator", 200, 2)
            .unwrap();
        assert!(resumed.captured_upper_bound.expect("captured feed head") > captured);
        assert_eq!(resumed.drain_cursor, 0);
        assert!(
            !(resumed.step_seed
                || resumed.step_memories
                || resumed.step_notes
                || resumed.step_compartments
                || resumed.step_reconcile
                || resumed.step_verify),
            "a wider capture must clear every completed step: {resumed:?}"
        );
        let resume_token = resumed.coordinator_token.as_deref().expect("resume token");
        assert!(
            store
                .authority_finish_drain(
                    "store-uuid",
                    "project",
                    "notes",
                    resumed.generation,
                    "hash",
                    "hash",
                    true,
                    resume_token,
                    3,
                )
                .is_err(),
            "the finish gate must stay closed until every step covers the widened capture"
        );

        mark_every_drain_step(&store, &resumed, 3);
        let finished = store
            .authority_finish_drain(
                "store-uuid",
                "project",
                "notes",
                resumed.generation,
                "hash",
                "hash",
                true,
                resume_token,
                4,
            )
            .unwrap();
        assert_eq!(finished.state, "TS");
    }

    #[test]
    fn authority_abort_prepare_keeps_the_recorded_checksum_verdict() {
        for (actual, verdict) in [("actual-hash", false), ("expected-hash", true)] {
            let dir = tempfile::tempdir().unwrap();
            let store = store(dir.path());
            let preparing = store
                .authority_begin_prepare("store-uuid", "project", "memories")
                .unwrap();
            let verified = store
                .authority_verify_prepare(
                    "store-uuid",
                    "project",
                    "memories",
                    preparing.generation,
                    "expected-hash",
                    actual,
                )
                .unwrap();
            assert_eq!(verified.checksum_ok, Some(verdict));

            let aborted = store
                .authority_abort_prepare("store-uuid", "project", "memories", preparing.generation)
                .unwrap();
            assert_eq!(aborted.state, "TS");
            assert_eq!(aborted.generation, preparing.generation + 1);
            assert_eq!(aborted.checksum_expected.as_deref(), Some("expected-hash"));
            assert_eq!(aborted.checksum_actual.as_deref(), Some(actual));
            assert_eq!(aborted.checksum_ok, Some(verdict));

            let next = store
                .authority_begin_prepare("store-uuid", "project", "memories")
                .unwrap();
            assert_eq!(
                (
                    next.checksum_expected,
                    next.checksum_actual,
                    next.checksum_ok
                ),
                (None, None, None),
                "the next preparation starts without the aborted verdict"
            );
        }
    }

